-- Modify "supply_connections" table
ALTER TABLE "supply_connections" ADD COLUMN "sync_task_id" bigint NOT NULL DEFAULT 0, ADD COLUMN "sync_lease_token" character varying NOT NULL DEFAULT '', ADD COLUMN "sync_lease_until" bigint NOT NULL DEFAULT 0;
-- Modify "supply_sync_tasks" table
ALTER TABLE "supply_sync_tasks" ADD COLUMN "request_key" character varying NULL, ADD COLUMN "request_hash" character varying NULL, ADD COLUMN "import_payload" jsonb NULL;
-- Create index "supplysynctask_connection_id_request_key" to table: "supply_sync_tasks"
CREATE UNIQUE INDEX "supplysynctask_connection_id_request_key" ON "supply_sync_tasks" ("connection_id", "request_key");
-- Create "supply_import_items" table
CREATE TABLE "supply_import_items" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "task_id" bigint NOT NULL, "code" character varying NOT NULL, "name" character varying NOT NULL, "snapshot" jsonb NOT NULL, "state" character varying NOT NULL DEFAULT 'pending', "stage" character varying NOT NULL DEFAULT 'import', "attempts" bigint NOT NULL DEFAULT 0, "next_attempt_at" bigint NOT NULL DEFAULT 0, "saved" boolean NOT NULL DEFAULT false, "created" boolean NOT NULL DEFAULT false, "activate_after_stock" boolean NOT NULL DEFAULT false, "local_product_id" bigint NOT NULL DEFAULT 0, "local_revision" character varying NOT NULL DEFAULT '', "error_code" character varying NOT NULL DEFAULT '', "error_summary" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "supplyimportitem_task_id_code" to table: "supply_import_items"
CREATE UNIQUE INDEX "supplyimportitem_task_id_code" ON "supply_import_items" ("task_id", "code");
-- Create index "supplyimportitem_task_id_state_next_attempt_at" to table: "supply_import_items"
CREATE INDEX "supplyimportitem_task_id_state_next_attempt_at" ON "supply_import_items" ("task_id", "state", "next_attempt_at");
